import urllib.request, json, re
base='https://raw.githubusercontent.com/embeddings-benchmark/leaderboard/main/boards_data/'
def get(lang, task):
    r=urllib.request.Request(base+lang+'/data_tasks/'+task+'/default.jsonl', headers={'User-Agent':'Mozilla/5.0'})
    out={}
    for line in urllib.request.urlopen(r, timeout=30).read().decode().strip().splitlines():
        d=json.loads(line)
        m=re.match(r'<a .+?>(.+)</a>', d['Model'])
        out[m.group(1)]=d
    return out
da_bm=get('da','BitextMining')
da_cl=get('da','Classification')
no_cl=get('no','Classification')
se_cl=get('se','Classification')
tasks={}
for k in da_bm['GritLM-7B']:
    if k=='BornholmBitextMining':
        tasks['da_BM']=(da_bm,k)
for src in (da_cl, no_cl, se_cl):
    for k in src['multilingual-e5-large']:
        if re.match(r'[A-Z][A-Za-z]+Classification', k) or k.startswith('Scala'):
            tasks[(id(src), k)]=(src,k)
all_models=set(da_bm)|set(da_cl)|set(no_cl)|set(se_cl)
rows=[]
for m in all_models:
    vals=[]
    for key,(src,k) in tasks.items():
        if m in src and isinstance(src[m].get(k),(int,float)):
            vals.append(src[m][k])
    if len(vals)==len(tasks):
        rows.append((sum(vals)/len(vals), m))
rows.sort(reverse=True)
print('total tasks', len(tasks))
for r in rows[:10]:
    print(r)
